(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,$=k=>document.getElementById('t-'+k),defaults=[0,6,9,13,19,25,32,38,50,63,75,100,125,150,200,250,300];
const products={rubber:{name:'ArmaFlex ACE Plus',k:.035,temp:0,sizes:[6,9,13,19,25,32],url:'https://www.armacell.com/sites/default/files/2025/03/28/ArmaFlex%20ACE%20Plus%20-%20Product%20Brochure%20-%20en-LT.pdf'},pe:{name:'Tubolit Tubes',k:.038,temp:10,sizes:[10,13,19,25,38],url:'https://www.armacell.com/en-US/product/technical-specs/tubolit-tubes'},glass:{name:'Knauf Atmosphere Duct Wrap',k:.035,temp:25,sizes:[25,50],url:'https://pim.knaufinsulation.com/files/download/kine3483dat-uae-duct-wrap-roll-datasheet.pdf'},rock:{name:'ROCKWOOL DuctWrap',k:.034,temp:10,sizes:[25,40,50],url:'https://www.rockwool.com/syssiteassets/rw-uk/downloads/datasheets/ductslab-ductwrap-datasheet.pdf'}};
function mountHelp(){
 if(document.getElementById('insulation-k-help'))return;
 const k=document.querySelector('[data-field="k"]'),margin=document.querySelector('[data-field="margin"]');
 k.insertAdjacentHTML('beforeend','<details id="insulation-k-help" class="insulation-help"><summary>'+L('Hướng dẫn chọn λ','Choosing conductivity')+'</summary><div><p>'+L('Hệ số dẫn nhiệt λ cho biết vật liệu truyền nhiệt nhiều hay ít. λ càng nhỏ, khả năng cách nhiệt càng tốt khi so sánh cùng chiều dày và điều kiện nhiệt độ. Đơn vị: W/(m·K).','Thermal conductivity λ describes how readily a material conducts heat. A lower λ provides better insulation at the same thickness and temperature conditions. Unit: W/(m·K).')+'</p><ul><li>'+L('Chọn vật liệu có sẵn: công cụ điền λ tham khảo, kèm tên sản phẩm và nhiệt độ công bố trong kết quả.','Select a preset: the tool fills a reference λ and identifies the product and published temperature in the results.')+'</li><li>'+L('Có catalogue: nhập λ của đúng sản phẩm tại nhiệt độ trung bình phù hợp. Nhiệt độ trung bình là giá trị đại diện trong lớp cách nhiệt, không chỉ là nhiệt độ môi trường.','Have a data sheet: enter the actual product conductivity at a suitable mean temperature. Mean temperature represents conditions within the insulation, rather than ambient temperature alone.')+'</li><li>'+L('Chưa chọn sản phẩm: giá trị mẫu chỉ dùng tính sơ bộ. Không dùng một λ cố định cho mọi sản phẩm cùng loại.','No product selected: the sample value is for preliminary calculations. Products of the same material type do not necessarily share the same conductivity.')+'</li><li>'+L('Cách nhiệt cũ hoặc bị ẩm: giá trị catalogue có thể không đại diện tình trạng thực tế.','Aged or wet insulation: the data-sheet value may not represent its actual condition.')+'</li></ul><p>'+L('Sửa λ sẽ chuyển vật liệu sang Tự nhập để tránh nhầm với thông số catalogue.','Editing λ switches the material to Custom to distinguish it from a catalogue preset.')+'</p></div></details>');
 margin.insertAdjacentHTML('beforeend','<details class="insulation-help"><summary>'+L('Hướng dẫn & chọn nhanh','Guide & quick selection')+'</summary><div><p>'+L('Ví dụ: điểm sương 25°C, khoảng an toàn 1°C → mục tiêu bề mặt 26°C. Các mức dưới đây là lựa chọn tham khảo của công cụ, không phải quy định chung của tiêu chuẩn.','Example: dew point 25°C plus a 1°C margin gives a 26°C surface target. The options below are tool reference settings, not universal standard requirements.')+'</p><div class="calc-table-scroll"><table class="calc-output-table"><thead><tr><th>'+L('Khoảng an toàn','Margin')+'</th><th>'+L('Ý nghĩa','Meaning')+'</th></tr></thead><tbody>'+[[0,L('Đúng ngưỡng điểm sương, không có dự phòng','Dew-point threshold, no allowance')],[1,L('Mặc định · dự phòng ban đầu cho tính sơ bộ','Default · initial allowance for preliminary checks')],[2,L('Thử phương án có dự phòng cao hơn','Try a larger allowance')],[3,L('Kiểm tra độ nhạy với dự phòng thêm','Check sensitivity to additional allowance')]].map(([v,t])=>'<tr><td><button type="button" class="text-button" data-insulation-margin="'+v+'" aria-label="'+L('Chọn khoảng an toàn ','Set margin to ')+v+' °C">'+v+' °C</button></td><td>'+t+'</td></tr>').join('')+'</tbody></table></div><p>'+L('Có thể tự nhập theo yêu cầu thiết kế hoặc nhà sản xuất. Dùng nhiệt độ và độ ẩm bất lợi dự kiến tại vị trí lắp đặt. Khoảng an toàn không thay thế việc kiểm tra mối nối, giá đỡ và lớp cản hơi.','Enter a custom value to suit design or manufacturer requirements. Use expected adverse temperature and humidity at the installation location. A margin does not replace checks of joints, supports and vapour barriers.')+'</p><a href="https://handbook.ashrae.org/Handbooks/F21/SI/F21_Ch23/F21_Ch23_si.aspx" target="_blank" rel="noopener noreferrer nofollow">ASHRAE — Insulation for Mechanical Systems ↗</a></div></details>');
 for(const field of [k,margin]){const help=field.querySelector(':scope > .field-help'),body=field.querySelector('.insulation-help > div');if(help&&body)body.prepend(help);}
 margin.addEventListener('click',e=>{const b=e.target.closest('[data-insulation-margin]');if(!b)return;$('margin').value=b.dataset.insulationMargin;$('margin').dispatchEvent(new Event('input',{bubbles:true}));});
}
function product(x){const p=products[x.material];return p&&x.material==='rock'&&x.shape==='rect'?{...p,name:'ROCKWOOL DuctSlab',k:.035,sizes:[40,50]}:p;}
function sync(){if(!$('application'))return;mountHelp();const duct=$('application').value==='duct',gas=$('application').value==='refrigerant';for(const k of ['refrigerantSystem','refrigerantLine','copperSize','manufacturerMin']){document.querySelector('[data-field="'+k+'"]').hidden=!gas;$(k).disabled=!gas;}if(!duct)$('shape').value='round';$('shape').disabled=!duct;const rect=duct&&$('shape').value==='rect';for(const k of ['width','height','d']){const active=k==='d'?!rect:rect;$ (k).disabled=!active;document.querySelector('[data-field="'+k+'"]').hidden=!active;}
 for(const o of $('material').options)o.disabled=(o.value==='pe'&&(duct||gas))||(['glass','rock'].includes(o.value)&&!duct);if($('material').selectedOptions[0]?.disabled)$('material').value='custom';
 const x={material:$('material').value,shape:$('shape').value},p=product(x),sizes=p?p.sizes:defaults.slice(1),old=$('thicknessQuick').value;
 $('thicknessQuick').innerHTML='<option value="custom">'+L('Tự nhập','Custom')+'</option>'+sizes.map(n=>'<option value="'+n+'">'+n+' mm</option>').join('');$('thicknessQuick').value=sizes.includes(Number(old))&&Number(old)===Number($('thickness').value)?old:'custom';
}
function change(el){if(el.id==='t-copperSize'&&el.value!=='custom')$('d').value=el.value;if(['t-material','t-shape','t-application'].includes(el.id)){sync();const p=product({material:$('material').value,shape:$('shape').value});if(p)$('k').value=p.k;$('thicknessQuick').value='custom';}if(el.id==='t-thicknessQuick'&&el.value!=='custom')$('thickness').value=el.value;}
function input(el){if(el.id==='t-copperSize'&&el.value!=='custom')$('d').value=el.value;if(el.id==='t-d')$('copperSize').value='custom';if(el.id==='t-thicknessQuick'&&el.value!=='custom')$('thickness').value=el.value;if(el.id==='t-k')$('material').value='custom';if(el.id==='t-thickness')$('thicknessQuick').value='custom';}
function description(x){const p=product(x);const gas=x.application==='refrigerant'?'<p class="calc-note">'+L('Hệ máy và loại đường ống dùng ghi nhận điều kiện, không tự chọn đường kính hoặc nhiệt độ. Nhập nhiệt độ mặt ống dưới cách nhiệt theo chế độ vận hành bất lợi; kiểm tra yêu cầu hãng cho cả làm lạnh và sưởi.','System and line type record the application; they do not size the refrigerant pipe or assign temperature. Enter the bare pipe surface temperature for the adverse operating mode and check manufacturer requirements for cooling and heating.')+'</p>':'';return gas+(p?'<p class="calc-note">'+L('Tham khảo vật liệu: ','Material reference: ')+p.name+' · λ = '+p.k+' W/(m·K) '+L('tại nhiệt độ trung bình ','at mean temperature ')+p.temp+' °C. '+L('Kiểm tra λ ở nhiệt độ vận hành, quy cách và khả năng cung cấp thực tế; có thể tự sửa λ.','Verify conductivity at operating temperature, dimensions and local availability; conductivity remains editable.')+' <a target="_blank" rel="noopener noreferrer nofollow" href="'+p.url+'">'+L('Catalogue','Data sheet')+' ↗</a></p>':'');}
window.HVACInsulationPresets={sync,change,input,description,sizes(x){const p=product(x);return p?[0,...p.sizes]:defaults;}};
})();
